// XOR Lattice - bitwise fractal, seam-free. Parametric (u,v) texture, animated colors.
//
// SEAM-FREE: the grid has a power-of-two number of cells per turn and every
// cell index is wrapped, so x XOR y repeats exactly: u = 0 meets u = 1 and
// v = 0 meets v = 1 with no jump (torus, sphere, cylinder, tubes).
// Surfaces glued with a twist (Klein bottle, Moebius band, Boy/Roman surface):
// set MIRROR_V (or MIRROR_U) to 1.0 -> that direction folds back on itself,
// like Soft Clouds, and closes on every surface.
// Stays seam-free with the dock zoom at 1, 1/2, 1/4... and any pan.
// Dock colors: u_col1 = light tint, u_col2 = deep tone.

const int   BITS_U    = 8;     // cells around u = 2^BITS_U          [4 .. 10]
const int   BITS_V    = 7;     // cells around v = 2^BITS_V          [4 .. 10]
const float RAINBOW   = 0.75;  // 0 = dock colors only, 1 = full spectrum
const float HUE_TURNS = 3.0;   // spectrum turns over the XOR range  [1 .. 6]
const float CYCLE     = 0.12;  // color cycling speed (0 = static)
const float BEVEL     = 0.35;  // dark groove between cells          [0 .. 0.6]
const vec2  SHIFT     = vec2(0.3183, 0.2071); // moves the strongest lines of the
                                         // pattern off the seams (any value works)
const float MIRROR_U  = 0.0;   // 1 = fold u (twisted gluing across the u seam)
const float MIRROR_V  = 0.0;   // 1 = fold v (Klein bottle, Moebius band)

// Mirrored direction: triangle wave 0 -> 0.5 -> 0, equal at both ends.
vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

vec3 xorPalette(float x) {
    vec3 base = mix(u_col2, u_col1, x);
    vec3 spectrum = 0.5 + 0.5 * cos(TAU * (x * HUE_TURNS - iTime * CYCLE + vec3(0.0, 0.33, 0.67)));
    return mix(base, spectrum * mix(vec3(1.0), u_col1, 0.45), RAINBOW);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 raw = fragCoord / iResolution.xy;
    vec2 uv = seamFold(raw) + SHIFT;

    ivec2 n = ivec2(1 << BITS_U, 1 << BITS_V);
    vec2 p = uv * vec2(n);
    ivec2 c = ivec2(floor(p)) & (n - 1);
    int top = max(n.x, n.y) - 1;
    float x = float((c.x ^ c.y) & top) / float(top);

    vec3 col = xorPalette(x);

    // Pixel size in cells. fract(raw + 0.5) has no jump where raw does: the
    // smaller of the two derivatives ignores the seam itself.
    vec2 fw = min(fwidth(raw), fwidth(fract(raw + 0.5))) * vec2(n);
    float px = max(fw.x, fw.y);

    // groove between cells, faded out when cells shrink to a few pixels
    vec2 f = fract(p);
    vec2 ed = min(f, 1.0 - f);
    float edge = min(ed.x, ed.y);
    float groove = 1.0 - smoothstep(0.0, max(1.2 * px, 0.06), edge);
    col *= 1.0 - BEVEL * groove * (1.0 - smoothstep(0.2, 0.45, px));

    // cells smaller than a pixel: average color instead of moire
    col = mix(col, xorPalette(0.5) * 0.85, smoothstep(0.7, 2.0, px));

    fragColor = vec4(col, 1.0);
}
